import{_ as r,C as a,o as t,c as i,a2 as e,b as s,w as o,a as l,E as u,a3 as n}from"./chunks/framework.BaXgE4DV.js";const f=JSON.parse('{"title":"데이터 모델","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/data-model.md","filePath":"architecture/data-model.md","lastUpdated":1791510387000}'),h={name:"architecture/data-model.md"};function b(p,d,m,g,q,A){const c=a("Mermaid");return t(),i("div",null,[d[1]||(d[1]=e('<h1 id="데이터-모델" tabindex="-1">데이터 모델 <a class="header-anchor" href="#데이터-모델" aria-label="Permalink to &quot;데이터 모델&quot;">​</a></h1><p>Firestore 컬렉션과 필드, 쓰는 주체, 지켜야 할 불변식을 정리합니다. 규칙의 세부 동작은 <a href="/grato-docs/architecture/security-rules">보안 규칙</a>에 있습니다.</p><h2 id="한눈에-보기" tabindex="-1">한눈에 보기 <a class="header-anchor" href="#한눈에-보기" aria-label="Permalink to &quot;한눈에 보기&quot;">​</a></h2><table tabindex="0"><thead><tr><th>컬렉션</th><th>문서 ID</th><th>쓰는 주체</th><th>읽는 주체</th><th>TTL</th></tr></thead><tbody><tr><td><code>users</code></td><td>uid</td><td>본인 (일부 필드는 서버)</td><td>본인</td><td>-</td></tr><tr><td><code>users/{uid}/blocks</code></td><td>차단한 uid</td><td>본인</td><td>본인</td><td>-</td></tr><tr><td><code>publicProfiles</code></td><td>uid</td><td>본인</td><td>로그인 사용자 (get만)</td><td>-</td></tr><tr><td><code>publicNames</code></td><td>sha256(publicName)</td><td>본인</td><td>로그인 사용자 (get만)</td><td>-</td></tr><tr><td><code>groups</code></td><td>자동 ID</td><td>서버 (관리자는 프로필 필드만)</td><td>멤버</td><td>-</td></tr><tr><td><code>inviteCodes</code></td><td>초대 코드</td><td>서버</td><td>로그인 사용자 (get만)</td><td>-</td></tr><tr><td><code>gratitudes</code></td><td>자동 ID</td><td>작성자 (+리액션·공개 전환·삭제) / 서버(<code>commentCount</code>, <code>moderation</code>)</td><td>작성자, 현재 그룹 멤버 (숨김 제외), 운영자 (공유된 글만)</td><td>-</td></tr><tr><td><code>gratitudes/{id}/comments</code></td><td>자동 ID</td><td>부모 글을 읽을 수 있는 사람 / 서버(<code>moderation</code>)</td><td>같은 범위 (숨김은 작성자만), 운영자 (공유된 글의 댓글만)</td><td>-</td></tr><tr><td><code>userStats</code></td><td>uid</td><td>서버</td><td>본인</td><td>-</td></tr><tr><td><code>userBadges</code></td><td>uid</td><td>서버</td><td>본인</td><td>-</td></tr><tr><td><code>badges</code></td><td><code>{condition}_{value}</code></td><td>관리자 / 서버(기본값 시드)</td><td>로그인 사용자</td><td>-</td></tr><tr><td><code>publicShares</code></td><td>uid</td><td>본인</td><td>본인, 서버</td><td>-</td></tr><tr><td><code>questions</code></td><td>자동 ID / <code>system_{kind}_{NN}</code></td><td>서버</td><td>선정된 질문: 로그인 사용자 / 그 밖: 제안자, 운영자</td><td>-</td></tr><tr><td><code>questionOriginals</code></td><td>질문 ID</td><td>서버</td><td>운영자</td><td>-</td></tr><tr><td><code>questionQuota</code></td><td><code>{uid}_{YYYYMMDD}</code></td><td>서버</td><td>없음</td><td>다음 날 끝</td></tr><tr><td><code>adminAuditLogs</code></td><td>자동 ID</td><td>서버</td><td>없음</td><td>-</td></tr><tr><td><code>reports</code></td><td>자동 ID / <code>auto_…</code> / <code>block_…</code></td><td>본인(생성만) / 서버</td><td>운영자</td><td>처리 후 1년</td></tr><tr><td><code>disabledUsers</code></td><td>uid</td><td>서버</td><td>없음</td><td>약 2시간</td></tr><tr><td><code>notificationLogs</code></td><td>이벤트 ID</td><td>서버</td><td>없음</td><td>30일</td></tr><tr><td><code>statsLogs</code></td><td>마커 ID</td><td>서버</td><td>없음</td><td>30일</td></tr><tr><td><code>pushTokens/{uid}/tokens</code></td><td>FCM 토큰</td><td>본인</td><td>본인, 서버</td><td>-</td></tr><tr><td><code>feedback</code></td><td>자동 ID</td><td>본인</td><td>본인, 관리자</td><td>-</td></tr><tr><td><code>analyticsEvents</code></td><td>자동 ID</td><td>본인 / 서버</td><td>관리자</td><td>-</td></tr></tbody></table><p>&quot;서버&quot;는 Admin SDK를 쓰는 Cloud Functions(또는 1회성 스크립트)입니다. Admin SDK는 보안 규칙을 거치지 않습니다.</p><p>예전 AI 글쓰기 기능이 쓰던 컬렉션은 기능과 함께 없앴습니다. 클라이언트 접근은 막혀 있고, 남은 문서는 <a href="/grato-docs/architecture/cloud-functions#purge-ai-data"><code>purgeAiData</code> 스크립트</a>로 지웁니다. → <a href="/grato-docs/decisions#adr-10">결정 기록 #10</a></p><h2 id="관계" tabindex="-1">관계 <a class="header-anchor" href="#관계" aria-label="Permalink to &quot;관계&quot;">​</a></h2>',7)),(t(),s(n,null,{default:o(()=>[u(c,{id:"mermaid-432",class:"mermaid",graph:"erDiagram%0A%20%20users%20%7C%7C--%7C%7C%20publicProfiles%20%3A%20%22%EA%B0%99%EC%9D%80%20uid%22%0A%20%20publicProfiles%20%7C%7C--o%7C%20publicNames%20%3A%20%22publicName%20%EC%84%A0%EC%A0%90%22%0A%20%20users%20%7Do--o%7B%20groups%20%3A%20%22groupIds%20%2F%20memberIds%22%0A%20%20groups%20%7C%7C--%7C%7B%20inviteCodes%20%3A%20%22groupId%22%0A%20%20users%20%7C%7C--o%7B%20gratitudes%20%3A%20%22userId%22%0A%20%20groups%20%7Co--o%7B%20gratitudes%20%3A%20%22groupId%20(%EC%97%86%EC%9C%BC%EB%A9%B4%20%EA%B0%9C%EC%9D%B8%20%EA%B8%80)%22%0A%20%20gratitudes%20%7C%7C--o%7B%20comments%20%3A%20%22%ED%95%98%EC%9C%84%20%EC%BB%AC%EB%A0%89%EC%85%98%22%0A%20%20users%20%7C%7C--o%7C%20userStats%20%3A%20%22%EA%B0%99%EC%9D%80%20uid%22%0A%20%20users%20%7C%7C--o%7C%20userBadges%20%3A%20%22%EA%B0%99%EC%9D%80%20uid%22%0A%20%20badges%20%7C%7C--o%7B%20userBadges%20%3A%20%22badgeId%22%0A%20%20users%20%7C%7C--o%7C%20publicShares%20%3A%20%22%EA%B0%99%EC%9D%80%20uid%22%0A%20%20users%20%7C%7C--o%7B%20pushTokens%20%3A%20%22%ED%95%98%EC%9C%84%20%EC%BB%AC%EB%A0%89%EC%85%98%22%0A%20%20users%20%7C%7C--o%7B%20questions%20%3A%20%22authorId%20(%EC%A0%9C%EC%95%88%ED%95%9C%20%EC%A7%88%EB%AC%B8)%22%0A%20%20questions%20%7C%7C--o%7C%20questionOriginals%20%3A%20%22%EA%B0%99%EC%9D%80%20ID%20(%EC%9A%B4%EC%98%81%EC%9E%90%EA%B0%80%20%EA%B3%A0%EC%B9%9C%20%EC%A7%88%EB%AC%B8)%22%0A%20%20users%20%7C%7C--o%7B%20blocks%20%3A%20%22%ED%95%98%EC%9C%84%20%EC%BB%AC%EB%A0%89%EC%85%98%20(%EC%B0%A8%EB%8B%A8%ED%95%9C%20%EC%82%AC%EC%9A%A9%EC%9E%90)%22%0A%20%20users%20%7C%7C--o%7B%20reports%20%3A%20%22reporterId%20(%EB%B3%B4%EB%82%B8%20%EC%8B%A0%EA%B3%A0)%22%0A%20%20reports%20%7Do--o%7C%20gratitudes%20%3A%20%22targetId%20(%EB%8C%80%EC%83%81%EC%9D%B4%20%EA%B8%80%EC%9D%BC%20%EB%95%8C)%22%0A"})]),fallback:o(()=>[...d[0]||(d[0]=[l(" Loading... ",-1)])]),_:1})),d[2]||(d[2]=e('<h2 id="사용자와-신원" tabindex="-1">사용자와 신원 <a class="header-anchor" href="#사용자와-신원" aria-label="Permalink to &quot;사용자와 신원&quot;">​</a></h2><h3 id="users" tabindex="-1"><code>users/{uid}</code> — 비공개 사용자 문서 <a class="header-anchor" href="#users" aria-label="Permalink to &quot;`users/{uid}` — 비공개 사용자 문서 {#users}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>타입</th><th>쓰는 주체</th><th>설명</th></tr></thead><tbody><tr><td><code>displayName</code></td><td>string</td><td>본인</td><td>표시 이름</td></tr><tr><td><code>email</code></td><td>string | null</td><td>본인</td><td>이메일 (이 문서에만 저장)</td></tr><tr><td><code>photoURL</code></td><td>string | null</td><td>본인</td><td>프로필 사진</td></tr><tr><td><code>tag</code></td><td>string</td><td>본인 (한 번만)</td><td>숫자 태그. 비어 있을 때만 설정 가능</td></tr><tr><td><code>publicName</code></td><td>string</td><td>본인</td><td>항상 <code>`${displayName} #${tag}`</code></td></tr><tr><td><code>groupIds</code></td><td>string[]</td><td><strong>서버</strong></td><td>참여 중인 Circle. 생성 시 빈 배열만 허용</td></tr><tr><td><code>createdAt</code></td><td>timestamp</td><td>본인 (한 번만)</td><td>서버 시간. 이후 변경 불가</td></tr><tr><td><code>notificationSettings</code></td><td>map</td><td>본인</td><td><code>dailyReminder</code>(기본 true), <code>dailyReminderHour</code>(기본 21), <code>dailyReminderMinute</code>(0·15·30·45, 기본 0), <code>reactionNotice</code>(기본 true), <code>circlePostNotice</code>(기본 true), <code>dailyReminderChannel</code>(앱이 로컬 알림을 맡으면 <code>&#39;local&#39;</code>, 아니면 <code>null</code>/없음), <code>dailyReminderLocalAt</code>(그때의 서버 시각) → <a href="/grato-docs/features/notifications#app">알림 설정</a></td></tr><tr><td><code>consent</code></td><td>map</td><td>본인</td><td>약관 동의와 만 14세 이상 확인. 정확히 <code>{ termsVersion, ageConfirmed: true, at }</code>(<code>at</code>은 서버 시간). 새 버전에 동의하면 통째로 다시 씀. 지우거나 일부만 고칠 수 없음 → <a href="/grato-docs/features/account#consent">약관 동의</a></td></tr><tr><td><code>isAdmin</code></td><td>bool</td><td><strong>콘솔/Admin SDK만</strong></td><td>관리자 페이지 접근, 질문 검토, 신고 처리, 배지 편집</td></tr></tbody></table><p>불변식</p><ul><li>본인만 읽고 쓸 수 있습니다. 다른 사람의 정보는 항상 <code>publicProfiles</code>로 봅니다(이메일 노출 방지).</li><li><code>groupIds</code>는 Circle callable만 바꿉니다. 탈퇴·삭제 후 남은 오래된 ID는 함수가 다음 생성·참여 때 정리합니다.</li><li>Circle callable이 클라이언트보다 먼저 문서를 만들 수 있습니다(<code>groupIds</code>만 있는 문서). 이 경우 다음 로그인 동기화에서 클라이언트가 <code>createdAt</code>과 알림 설정을 채웁니다.</li><li><code>consent</code>가 없거나 <code>termsVersion</code>이 현재 버전(<code>src/content/legal.js</code>의 <code>TERMS_VERSION</code>)과 다르면 클라이언트가 동의 화면을 보여 줍니다. 감사 글·댓글 생성 규칙은 <code>consent</code>가 있는지 확인합니다.</li><li>클라이언트는 삭제할 수 없습니다. 계정 삭제는 <code>deleteAccount</code> callable이 하위 컬렉션(<code>blocks</code>)과 함께 지웁니다. → <a href="/grato-docs/features/account#deletion">계정 삭제</a></li></ul><h3 id="blocks" tabindex="-1"><code>users/{uid}/blocks/{blockedUid}</code> — 차단 목록 <a class="header-anchor" href="#blocks" aria-label="Permalink to &quot;`users/{uid}/blocks/{blockedUid}` — 차단 목록 {#blocks}&quot;">​</a></h3><p><code>createdAt</code>(서버 시간) 하나만 가집니다. 문서 ID가 차단한 사용자의 uid입니다.</p><ul><li>본인만 읽고, 만들고(자기 자신은 차단 불가), 지웁니다(차단 해제). 다시 차단(<code>setDoc</code>)은 같은 형태의 수정으로 허용됩니다.</li><li>클라이언트는 이 목록으로 차단한 사람의 글·댓글을 화면에서 거르고, 알림 트리거(Admin SDK)는 받는 사람이 보낸 사람을 차단했으면 건너뜁니다. 새 차단은 <code>onBlockCreated</code>가 운영자 대기열에 낮은 우선순위 신고로 남깁니다. → <a href="/grato-docs/features/safety#block">차단</a></li></ul><h3 id="publicprofiles-uid-—-공개-프로필" tabindex="-1"><code>publicProfiles/{uid}</code> — 공개 프로필 <a class="header-anchor" href="#publicprofiles-uid-—-공개-프로필" aria-label="Permalink to &quot;`publicProfiles/{uid}` — 공개 프로필&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>displayName</code></td><td>1~100자</td></tr><tr><td><code>tag</code></td><td>1~10자, 한 번 정해지면 변경 불가</td></tr><tr><td><code>publicName</code></td><td><code>`${displayName} #${tag}`</code> — 전역 유일</td></tr><tr><td><code>photoURL</code></td><td>본인 Storage 업로드(<code>profilePhotos/{uid}/…</code>) 또는 본인 ID 토큰의 Google 아바타, 또는 null</td></tr></tbody></table><ul><li>정확히 이 4개 필드만 가집니다. 로그인한 사용자는 문서 하나씩 <strong>get</strong>만 할 수 있고 목록 조회는 불가능합니다(사용자 목록 수집 방지).</li><li>글·댓글의 작성자 필드(<code>authorName</code>, <code>authorTag</code>, <code>authorPublicName</code>, <code>authorPhotoURL</code>)는 이 문서와 같아야 생성됩니다.</li><li><code>displayName</code>이 바뀌면 <code>onPublicNameWritten</code>이 내용 필터로 검사해, 걸리면 이름은 그대로 두고 운영자 대기열에 신고를 남깁니다. → <a href="/grato-docs/features/safety#auto-moderation">자동 숨김: 이름</a></li><li>클라이언트는 삭제할 수 없습니다(<code>deleteAccount</code>가 지움). 차단 목록에 남은 삭제된 계정은 프로필이 없어 &quot;알 수 없는 사용자&quot;로 보입니다.</li></ul><h3 id="publicnames-key-—-공개-이름-선점" tabindex="-1"><code>publicNames/{key}</code> — 공개 이름 선점 <a class="header-anchor" href="#publicnames-key-—-공개-이름-선점" aria-label="Permalink to &quot;`publicNames/{key}` — 공개 이름 선점&quot;">​</a></h3><p><code>key</code>는 <code>publicName</code>의 UTF-8 바이트를 SHA-256으로 해시한 소문자 16진수입니다. 클라이언트(<code>src/lib/publicName.js</code>), 함수(<code>functions/src/utils/publicName.ts</code>), 규칙(<code>hashing.sha256</code>)이 같은 계산을 합니다.</p><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>uid</code></td><td>이름을 가진 사용자</td></tr><tr><td><code>publicName</code></td><td>원문 이름</td></tr></tbody></table><ul><li><strong>먼저 만든 사람이 임자</strong>입니다. 생성만 가능하고 덮어쓸 수 없습니다.</li><li>자기 프로필이 같은 배치에서 그 이름을 갖게 될 때만 만들 수 있고, 이름을 바꿀 때 예전 선점은 같은 배치에서 지워야 합니다.</li><li>프로필·선점·<code>users</code>는 항상 하나의 배치로 함께 씁니다(<code>src/lib/firestore.js</code>).</li><li>선점 제도 이전에 만들어진 이름은 <code>backfillPublicNames</code> 스크립트로 선점 문서를 만들어 둡니다. → <a href="/grato-docs/architecture/cloud-functions#backfill">Cloud Functions</a></li></ul><h2 id="circle" tabindex="-1">Circle <a class="header-anchor" href="#circle" aria-label="Permalink to &quot;Circle&quot;">​</a></h2><h3 id="groups-groupid" tabindex="-1"><code>groups/{groupId}</code> <a class="header-anchor" href="#groups-groupid" aria-label="Permalink to &quot;`groups/{groupId}`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>쓰는 주체</th><th>설명</th></tr></thead><tbody><tr><td><code>name</code></td><td>서버 생성 / 관리자 수정</td><td>1~30자</td></tr><tr><td><code>description</code></td><td>서버 생성 / 관리자 수정</td><td>최대 100자</td></tr><tr><td><code>photoURL</code></td><td>관리자</td><td>Circle 사진 (null 가능)</td></tr><tr><td><code>adminId</code></td><td>서버</td><td>관리자 uid. 관리자가 계정을 삭제하면 가장 오래 함께한 멤버로 바뀜(그 밖의 변경 기능 없음)</td></tr><tr><td><code>memberIds</code></td><td>서버</td><td>멤버 uid 목록, 최대 50명</td></tr><tr><td><code>removedIds</code></td><td>서버</td><td>관리자가 내보낸 uid. 다시 허용(unban) 전까지 초대 코드로 재참여 불가</td></tr><tr><td><code>inviteCode</code></td><td>서버</td><td>현재 초대 코드</td></tr><tr><td><code>plan</code></td><td>서버</td><td><code>&quot;free&quot;</code></td></tr><tr><td><code>createdAt</code></td><td>서버</td><td>생성 시각</td></tr></tbody></table><p>불변식</p><ul><li><code>memberIds</code>에는 항상 <code>adminId</code>가 들어 있고, 관리자는 탈퇴·내보내기 대상이 아닙니다.</li><li><code>users/{uid}.groupIds</code>와 <code>memberIds</code>는 같은 트랜잭션에서 함께 바뀝니다.</li><li>존재하지 않는 Circle 문서에 대한 get은 오류가 아니라 빈 결과를 돌려줍니다. 클라이언트는 이것으로 &quot;삭제된 Circle&quot;과 &quot;권한/네트워크 오류&quot;를 구분합니다.</li><li><code>memberIds</code>는 참여 순서입니다(생성자가 처음, 참여는 뒤에 붙음). 계정 삭제 때 관리자를 넘겨받을 &quot;가장 오래 함께한 멤버&quot;를 이 순서로 정합니다.</li><li>관리자가 이름·설명을 바꾸면 <code>onCircleNameWritten</code>이 내용 필터로 검사해, 걸리면 운영자 대기열에 신고를 남깁니다(이름은 그대로). 생성 때는 <code>createCircle</code>이 거절합니다.</li><li>운영자(<code>users.isAdmin</code>)는 신고된 Circle을 확인하려고 문서 하나를 get할 수 있습니다(목록 조회는 불가).</li></ul><h3 id="invitecodes-code" tabindex="-1"><code>inviteCodes/{CODE}</code> <a class="header-anchor" href="#invitecodes-code" aria-label="Permalink to &quot;`inviteCodes/{CODE}`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>groupId</code></td><td>대상 Circle</td></tr><tr><td><code>createdBy</code></td><td>발급한 관리자 (그 사람이 계정을 삭제하면 null)</td></tr><tr><td><code>createdAt</code></td><td>발급 시각</td></tr><tr><td><code>expiresAt</code></td><td>발급 후 30일</td></tr><tr><td><code>maxUses</code></td><td>50</td></tr><tr><td><code>useCount</code></td><td>참여에 성공한 횟수 (이미 멤버인 경우는 세지 않음)</td></tr></tbody></table><ul><li>새 코드는 8자리이며, 헷갈리는 <code>0 O 1 I</code>를 뺀 32개 문자로 만듭니다.</li><li>예전 6자리 코드는 <code>expiresAt</code>·<code>maxUses</code>가 없을 수 있고, 없으면 무제한으로 취급합니다.</li><li><code>expiresAt</code>은 TTL 필드가 <strong>아닙니다</strong>. 만료 판단은 <code>joinCircle</code>이 하고, 문서는 코드 재발급·Circle 삭제 때 지워집니다.</li><li>클라이언트는 아는 코드 하나를 get할 수만 있습니다(목록 조회 불가).</li></ul><h2 id="감사-글" tabindex="-1">감사 글 <a class="header-anchor" href="#감사-글" aria-label="Permalink to &quot;감사 글&quot;">​</a></h2><h3 id="gratitudes-gratitudeid" tabindex="-1"><code>gratitudes/{gratitudeId}</code> <a class="header-anchor" href="#gratitudes-gratitudeid" aria-label="Permalink to &quot;`gratitudes/{gratitudeId}`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>쓰는 주체</th><th>설명</th></tr></thead><tbody><tr><td><code>userId</code></td><td>작성자 (생성 시)</td><td>작성자 uid</td></tr><tr><td><code>groupId</code></td><td>작성자 (생성 시) / 서버 (숨김·해제)</td><td>Circle ID 또는 null(개인 글). 숨긴 Circle 글은 null이 되고 원래 Circle은 <code>moderation.groupId</code>로 옮겨짐</td></tr><tr><td><code>title</code></td><td>작성자 (생성 시)</td><td>0~100자</td></tr><tr><td><code>content</code></td><td>작성자 (생성 시)</td><td>1~3000자</td></tr><tr><td><code>authorName</code>, <code>authorTag</code>, <code>authorPublicName</code>, <code>authorPhotoURL</code></td><td>작성자 (생성 시)</td><td><code>publicProfiles/{uid}</code>의 사본 (피드 읽기 비용 절감용 비정규화)</td></tr><tr><td><code>reactions</code></td><td>읽을 수 있는 사람</td><td><code>{ &quot;❤️&quot;: [uid], &quot;🙏&quot;: [], &quot;✨&quot;: [], &quot;🔥&quot;: [] }</code></td></tr><tr><td><code>isPublic</code></td><td>작성자</td><td>외부 공유 허용 여부. 생성 시 항상 false</td></tr><tr><td><code>sharedAt</code></td><td>작성자</td><td>공개한 시각(서버 시간) 또는 null</td></tr><tr><td><code>commentCount</code></td><td><strong>서버</strong></td><td>댓글 수</td></tr><tr><td><code>moderation</code></td><td><strong>서버</strong></td><td>숨김 기록 (없으면 정상). 아래 <a href="#moderation">moderation</a></td></tr><tr><td><code>createdAt</code></td><td>작성자 (생성 시)</td><td>서버 시간</td></tr></tbody></table><p>불변식</p><ul><li>문서 ID는 클라이언트 자동 ID(영숫자 20자)만 허용됩니다. 서버 마커 ID가 이 값으로 만들어지기 때문입니다.</li><li>생성 후 클라이언트가 바꿀 수 있는 것은 ① 리액션(본인 uid 추가·제거), ② 작성자의 <code>isPublic</code>/<code>sharedAt</code>뿐입니다. 서버는 <code>commentCount</code>와 <code>moderation</code>(숨김 때 <code>groupId</code> 포함)을 바꿉니다. 내용·작성자는 아무도 고칠 수 없습니다.</li><li>새 글은 기본이 &quot;나만 보기&quot;(<code>groupId: null</code>)입니다. Circle 공유는 작성 화면에서 직접 고를 때만 됩니다. → <a href="/grato-docs/features/gratitudes#visibility">공개 범위</a>, <a href="/grato-docs/decisions#adr-12">결정 기록 #12</a></li><li>홈의 &quot;내 기록&quot;은 <code>userId == 나</code> + <code>createdAt</code> 내림차순 쿼리(기존 인덱스)로 개인 글과 Circle에 공유한 글을 함께 읽습니다.</li><li>작성자는 Circle을 떠나거나 Circle이 삭제된 뒤에도, 글이 숨겨진 동안에도 자기 글을 읽을 수 있습니다(개인 기록으로 보존).</li><li><strong>작성자만 삭제할 수 있습니다.</strong> 삭제하면 <code>onGratitudeDeleted</code>가 댓글 하위 컬렉션을 지우고, 통계를 남은 글로 다시 계산하고, 그 달에 글이 남지 않으면 공유한 캘린더 월을 비공개로 돌립니다. 받은 배지는 유지됩니다. → <a href="/grato-docs/features/gratitudes#delete">감사 글: 삭제</a></li><li>생성 규칙은 약관 동의(<code>users.consent</code>)와 계정 잠금이 없는지(<code>disabledUsers</code>)를 함께 확인합니다.</li><li>예전 문서에는 <code>isPublic</code>이 없거나 다른 이모지 키가 있을 수 있습니다. 규칙은 이를 허용하되 기존 키는 바꾸지 못하게 합니다.</li></ul><h3 id="gratitudes-id-comments-commentid" tabindex="-1"><code>gratitudes/{id}/comments/{commentId}</code> <a class="header-anchor" href="#gratitudes-id-comments-commentid" aria-label="Permalink to &quot;`gratitudes/{id}/comments/{commentId}`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>userId</code></td><td>댓글 작성자</td></tr><tr><td><code>authorName</code>, <code>authorTag</code>, <code>authorPublicName</code>, <code>authorPhotoURL</code></td><td><code>publicProfiles/{uid}</code>와 동일해야 함</td></tr><tr><td><code>content</code></td><td>1~500자</td></tr><tr><td><code>moderation</code></td><td><strong>서버</strong>. 숨김 기록 (없으면 정상)</td></tr><tr><td><code>createdAt</code></td><td>서버 시간</td></tr></tbody></table><ul><li>수정은 불가. 삭제는 댓글 작성자 또는 부모 글 작성자.</li><li>생성·삭제 시 트리거가 부모의 <code>commentCount</code>를 ±1 합니다(0 아래로 내려가지 않음). 숨긴 댓글도 셉니다(작성자에게는 보이므로).</li><li>계정 삭제가 사용자의 모든 댓글을 찾을 수 있도록 <code>comments.userId</code>에 컬렉션 그룹 인덱스가 있습니다.</li></ul><h3 id="moderation" tabindex="-1"><code>moderation</code> 필드 <a class="header-anchor" href="#moderation" aria-label="Permalink to &quot;`moderation` 필드 {#moderation}&quot;">​</a></h3><p>글과 댓글에 서버(자동 숨김 트리거, <code>moderate</code> callable)만 쓰는 숨김 기록입니다. 클라이언트는 만들 때도 수정할 때도 이 필드를 쓸 수 없습니다.</p><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>hidden</code> | <code>visible</code> (운영자가 숨김을 해제함)</td></tr><tr><td><code>source</code></td><td><code>auto</code>(필터) | <code>admin</code>(운영자)</td></tr><tr><td><code>reason</code></td><td><code>profanity</code>(필터) 또는 null(운영자)</td></tr><tr><td><code>at</code></td><td>서버 시간</td></tr><tr><td><code>groupId</code></td><td>글만. 숨긴 동안 원래 Circle ID, 보이는 동안 null</td></tr></tbody></table><ul><li><code>status == &quot;hidden&quot;</code>이면 작성자(&quot;검토 중이에요&quot;)와 운영자에게만 보입니다. → <a href="/grato-docs/features/safety#auto-moderation">자동 숨김</a></li><li>숨긴 Circle 글은 <code>groupId</code>가 null이라 Circle 피드 쿼리(<code>groupId ==</code>)에 나오지 않습니다. 화면 표시용 Circle은 <code>circleIdOf()</code>(<code>groupId ?? moderation.groupId</code>)로 구합니다.</li><li>기록이 하나라도 있으면 필터는 다시 건드리지 않습니다. 운영자의 결정이 항상 우선합니다.</li></ul><h2 id="통계와-배지" tabindex="-1">통계와 배지 <a class="header-anchor" href="#통계와-배지" aria-label="Permalink to &quot;통계와 배지&quot;">​</a></h2><h3 id="userstats-uid-—-서버-계산" tabindex="-1"><code>userStats/{uid}</code> — 서버 계산 <a class="header-anchor" href="#userstats-uid-—-서버-계산" aria-label="Permalink to &quot;`userStats/{uid}` — 서버 계산&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>totalGratos</code></td><td>전체 감사 수</td></tr><tr><td><code>currentStreak</code></td><td>마지막 기록일 기준 연속일</td></tr><tr><td><code>thisMonthCount</code></td><td><code>monthKey</code> 달의 감사 수</td></tr><tr><td><code>lastGratoDateKey</code></td><td>마지막 기록일 <code>YYYY-MM-DD</code> (KST)</td></tr><tr><td><code>monthKey</code></td><td><code>YYYY-MM</code> (KST)</td></tr><tr><td><code>lastGratoDate</code></td><td>마지막 기록 시각 (예전 문서 호환용으로도 사용)</td></tr></tbody></table><p>저장된 <code>currentStreak</code>은 &quot;마지막 기록일 기준&quot; 값입니다. 화면에는 마지막 기록이 오늘·어제(KST)일 때만 보여 줍니다. → <a href="/grato-docs/features/stats-badges">통계와 배지</a></p><p>글이 삭제되면 <code>onGratitudeDeleted</code>가 남은 글로 모든 필드를 다시 계산합니다(문서가 있을 때만 — 계정 삭제 뒤에 늦게 실행돼도 되살리지 않음). → <a href="/grato-docs/features/stats-badges#rebuild">통계: 글 삭제</a></p><h3 id="userbadges-uid-—-서버-계산" tabindex="-1"><code>userBadges/{uid}</code> — 서버 계산 <a class="header-anchor" href="#userbadges-uid-—-서버-계산" aria-label="Permalink to &quot;`userBadges/{uid}` — 서버 계산&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>badges</code></td><td><code>[{ badgeId, earnedAt }]</code> — 중복 없음</td></tr><tr><td><code>lastUpdated</code></td><td>서버 시간</td></tr></tbody></table><h3 id="badges-badgeid-—-배지-정의" tabindex="-1"><code>badges/{badgeId}</code> — 배지 정의 <a class="header-anchor" href="#badges-badgeid-—-배지-정의" aria-label="Permalink to &quot;`badges/{badgeId}` — 배지 정의&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>name</code>, <code>description</code>, <code>icon</code></td><td>표시 정보</td></tr><tr><td><code>condition</code></td><td><code>gratitude_count</code> | <code>streak</code> | <code>circle_count</code> | <code>reactions_received</code> | <code>shares</code> | <code>questions_selected</code></td></tr><tr><td><code>conditionValue</code></td><td>기준값</td></tr><tr><td><code>enabled</code></td><td>false면 평가·표시 제외 (필드가 없으면 활성)</td></tr><tr><td><code>sortOrder</code></td><td>표시 순서</td></tr><tr><td><code>badgeType</code></td><td><code>core</code> | <code>monthly</code> | <code>limited</code> | <code>social</code> (선택)</td></tr><tr><td><code>startAt</code>, <code>endAt</code></td><td>기간 한정 배지의 활성 기간 (선택)</td></tr><tr><td><code>seasonKey</code></td><td>시즌 구분 키 (선택)</td></tr><tr><td><code>shareable</code></td><td>공유 가능 여부 (선택)</td></tr><tr><td><code>createdAt</code></td><td>생성 시각</td></tr></tbody></table><p>문서 ID는 항상 <code>{condition}_{conditionValue}</code>(예: <code>streak_7</code>)입니다. 시드 데이터, 관리자 생성, <code>userBadges</code> 참조가 같은 ID를 쓰도록 하기 위해서입니다.</p><h2 id="공유" tabindex="-1">공유 <a class="header-anchor" href="#공유" aria-label="Permalink to &quot;공유&quot;">​</a></h2><h3 id="publicshares-uid-—-공유-opt-in-목록" tabindex="-1"><code>publicShares/{uid}</code> — 공유 opt-in 목록 <a class="header-anchor" href="#publicshares-uid-—-공유-opt-in-목록" aria-label="Permalink to &quot;`publicShares/{uid}` — 공유 opt-in 목록&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>calendarMonths</code></td><td>공개한 캘린더 월 <code>YYYY-MM</code> 목록 (최대 120개)</td></tr><tr><td><code>badgeIds</code></td><td>공개한 배지 ID 목록 (최대 200개)</td></tr></tbody></table><p>본인만 읽고 씁니다. <code>shareRenderer</code>는 여기에 있는 달·배지에 대해서만 이름과 기록을 보여 줍니다. 감사 글의 공개 여부는 이 문서가 아니라 글의 <code>isPublic</code>에 있습니다. 글을 지워 공개한 달에 글이 하나도 남지 않으면 <code>onGratitudeDeleted</code>가 그 달을 목록에서 뺍니다.</p><h2 id="questions" tabindex="-1">질문 제안 <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;질문 제안 {#questions}&quot;">​</a></h2><p>&quot;질문으로 쓰기&quot;의 질문과 사용자가 제안한 질문입니다. 모든 쓰기는 <code>submitQuestion</code>·<code>reviewQuestion</code> callable과 <code>seedQuestions</code> 스크립트가 합니다. 클라이언트는 운영자도 읽기만 합니다. → <a href="/grato-docs/features/questions">질문 제안과 선정</a>, <a href="/grato-docs/decisions#adr-11">결정 기록 #11</a></p><h3 id="questions-questionid" tabindex="-1"><code>questions/{questionId}</code> <a class="header-anchor" href="#questions-questionid" aria-label="Permalink to &quot;`questions/{questionId}`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>text</code></td><td>5~80자(코드 포인트). NFC, 보이지 않는 문자(폭 없는 공백, 한글 채움 문자 등)·제어 문자 제거, 연속 공백을 한 칸으로 정리한 뒤 저장</td></tr><tr><td><code>kind</code></td><td><code>opening</code>(첫 질문) | <code>followup</code>(이어지는 질문)</td></tr><tr><td><code>status</code></td><td><code>pending</code> | <code>approved</code> | <code>rejected</code> | <code>hidden</code></td></tr><tr><td><code>source</code></td><td><code>user</code> | <code>system</code></td></tr><tr><td><code>authorId</code></td><td>제안자 uid (기본 질문은 null. 제안자가 계정을 삭제하면 선정·숨김 질문은 null로 남고, 검토 중·반려 질문은 삭제)</td></tr><tr><td><code>authorPublicName</code></td><td>질문에 함께 표시할 공개 이름. 제출 때 <code>publicProfiles</code>에서 복사하고 선정 때 다시 읽음. 이름이 없거나 내용 필터에 걸리면 null(표시 안 함)</td></tr><tr><td><code>dupKey</code></td><td>중복 확인용 키: NFKC, 보이지 않는 문자 제거, 소문자, 글자와 숫자만</td></tr><tr><td><code>rejectReason</code></td><td>반려 사유 (선택, 100자 이내)</td></tr><tr><td><code>createdAt</code>, <code>approvedAt</code></td><td>제출·선정 시각. <code>approvedAt</code>은 마지막 선정 시각이고, 선정 전에 없었으면 &quot;처음 선정&quot;으로 보고 알림을 보냄</td></tr></tbody></table><ul><li>기본 질문은 <code>src/content/questions.json</code>이 원본이고, ID는 <code>system_opening_01..30</code>, <code>system_followup_01..10</code>입니다.</li><li><strong>선정된 질문 문서는 로그인한 누구나 통째로 읽을 수 있습니다.</strong> 그래서 공개되면 안 되는 값은 이 문서에 두지 않습니다. 검토한 운영자의 uid는 <code>adminAuditLogs</code>에만, 운영자가 고치기 전 제안 원문은 <code>questionOriginals</code>에만 저장합니다.</li><li>상태 변경: 선정은 <code>pending</code>·<code>hidden</code>에서, 반려는 <code>pending</code>에서, 숨김은 <code>approved</code>에서만 됩니다. → <a href="/grato-docs/features/questions#status">상태</a></li><li>질문 문서에는 <code>originalText</code> 필드를 두지 않습니다. 선정과 시드는 이 필드가 있으면 지웁니다(선정 때는 <code>questionOriginals</code>로 옮김).</li></ul><h3 id="questionoriginals-questionid" tabindex="-1"><code>questionOriginals/{questionId}</code> <a class="header-anchor" href="#questionoriginals-questionid" aria-label="Permalink to &quot;`questionOriginals/{questionId}`&quot;">​</a></h3><p><code>originalText</code>, <code>editedAt</code>. 운영자가 선정하면서 문구를 고쳤을 때, 처음 고치기 전의 제안 원문입니다. 운영자만 읽습니다.</p><h3 id="questionquota-uid-yyyymmdd" tabindex="-1"><code>questionQuota/{uid}_{YYYYMMDD}</code> <a class="header-anchor" href="#questionquota-uid-yyyymmdd" aria-label="Permalink to &quot;`questionQuota/{uid}_{YYYYMMDD}`&quot;">​</a></h3><p><code>count</code>(오늘 받아들여진 제안 수, 한도 5), <code>attempts</code>(오늘 서버까지 온 제안 시도 수, 거절 포함, 한도 30), <code>expireAt</code>(다음 날 끝, KST — TTL). 날짜는 KST 기준이고, <code>submitQuestion</code>이 트랜잭션 안에서 읽고 씁니다. 클라이언트는 접근할 수 없습니다.</p><h3 id="adminauditlogs-id" tabindex="-1"><code>adminAuditLogs/{id}</code> <a class="header-anchor" href="#adminauditlogs-id" aria-label="Permalink to &quot;`adminAuditLogs/{id}`&quot;">​</a></h3><p>운영자 작업 기록이며, 작업과 같은 트랜잭션(또는 배치)에서 남습니다(<code>utils/adminAudit.ts</code>). 운영자의 신원은 여기에만 남습니다. 클라이언트는 운영자도 접근할 수 없고, 콘솔에서 확인합니다.</p><table tabindex="0"><thead><tr><th>필드</th><th>설명</th></tr></thead><tbody><tr><td><code>actorUid</code></td><td>작업한 운영자. 계정 삭제 기록은 null</td></tr><tr><td><code>action</code></td><td>질문: <code>approve</code> | <code>reject</code> | <code>hide</code>. 신고 처리: <code>moderate_hide</code> | <code>moderate_unhide</code> | <code>moderate_delete</code> | <code>moderate_dismiss</code> | <code>moderate_disableUser</code>. 계정 삭제: <code>account_deleted</code></td></tr><tr><td><code>targetType</code>, <code>targetId</code></td><td>대상. 이용 정지는 <code>user</code>와 정지한 uid. 계정 삭제 기록과, 삭제된 사용자에 대한 기록의 <code>targetId</code>는 null</td></tr><tr><td><code>details</code></td><td>개인정보가 아닌 부가 정보(선택): 처리한 신고 ID, 신고된 대상, 계정 삭제 때 지운 항목 수와 Apple 연결 해제 여부</td></tr><tr><td><code>at</code></td><td>서버 시간</td></tr></tbody></table><h2 id="safety" tabindex="-1">안전 (신고·계정 잠금) <a class="header-anchor" href="#safety" aria-label="Permalink to &quot;안전 (신고·계정 잠금) {#safety}&quot;">​</a></h2><p>신고·차단·자동 숨김의 동작은 <a href="/grato-docs/features/safety">신고·차단과 자동 숨김</a>에 있습니다. 차단 목록은 <a href="#blocks"><code>users/{uid}/blocks</code></a>, 숨김 기록은 <a href="#moderation"><code>moderation</code></a>을 보세요.</p><h3 id="reports" tabindex="-1"><code>reports/{reportId}</code> <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;`reports/{reportId}` {#reports}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>필드</th><th>쓰는 주체</th><th>설명</th></tr></thead><tbody><tr><td><code>reporterId</code></td><td>신고자</td><td>신고한 uid. 자동 숨김·이름 필터는 <code>&quot;system&quot;</code>. 신고자가 계정을 삭제하면 null</td></tr><tr><td><code>targetType</code></td><td>신고자</td><td><code>gratitude</code> | <code>comment</code> | <code>user</code> | <code>circle</code> | <code>question</code></td></tr><tr><td><code>targetId</code></td><td>신고자</td><td>대상 문서 ID. 삭제된 사용자에 대한 신고는 <code>&quot;deleted&quot;</code></td></tr><tr><td><code>parentId</code></td><td>신고자</td><td>댓글이면 부모 글 ID (필수), 그 밖은 없음 또는 null</td></tr><tr><td><code>reason</code></td><td>신고자</td><td><code>spam</code> | <code>abuse</code> | <code>sexual</code> | <code>hate</code> | <code>self_harm</code> | <code>privacy</code> | <code>other</code></td></tr><tr><td><code>detail</code></td><td>신고자</td><td>자세한 내용, 500자 이하 (빈 값 가능)</td></tr><tr><td><code>status</code></td><td>신고자(<code>open</code>) / 서버</td><td><code>open</code> → <code>resolved</code> | <code>dismissed</code> (운영자) 또는 <code>spam</code> (도배)</td></tr><tr><td><code>createdAt</code></td><td>신고자</td><td>서버 시간</td></tr><tr><td><code>targetOwnerId</code>, <code>targetPreview</code></td><td>서버</td><td>대상의 작성자(Circle은 관리자)와 200자 발췌. &quot;나만 보기&quot; 글은 발췌 없음. 그 사람이 계정을 삭제하면 null</td></tr><tr><td><code>source</code>, <code>violation</code></td><td>서버</td><td>시스템 신고: <code>auto</code>(필터, <code>violation: &quot;profanity&quot;</code>) 또는 <code>block</code>(차단)</td></tr><tr><td><code>resolution</code>, <code>resolvedAt</code></td><td>서버</td><td>운영자 작업(<code>hide</code>, <code>delete</code>, <code>dismiss</code> …)과 시각</td></tr><tr><td><code>expireAt</code></td><td>서버</td><td>닫힌 시각 + 1년 (TTL)</td></tr></tbody></table><ul><li>사용자가 만드는 신고는 <strong>자동 ID</strong>만 허용합니다(<code>addDoc</code>). 서버가 만드는 신고는 정해진 ID를 써서 한 번만 만들어집니다: <code>auto_{type}_{id}</code>, <code>auto_comment_{글}_{댓글}</code>(자동 숨김), <code>auto_{user|circle}_{id}_{이름 키}</code>(이름 필터), <code>block_{차단한 uid}_{차단된 uid}</code>(차단).</li><li>운영자만 읽습니다. 신고한 사람도 자기 신고를 다시 읽을 수 없습니다. 상태 변경과 익명화는 모두 서버가 합니다.</li><li>처리한 운영자의 uid는 신고가 아니라 <code>adminAuditLogs</code>에 남습니다.</li></ul><h3 id="disabled-users" tabindex="-1"><code>disabledUsers/{uid}</code> <a class="header-anchor" href="#disabled-users" aria-label="Permalink to &quot;`disabledUsers/{uid}` {#disabled-users}&quot;">​</a></h3><p><code>reason</code>(<code>deleted</code> | <code>disabled</code>), <code>at</code>, <code>expireAt</code>(2시간 뒤, TTL). 계정 삭제(<code>deleteAccount</code>)나 이용 정지(<code>moderate</code>의 <code>disableUser</code>) 직후에 서버가 씁니다.</p><ul><li>Firebase Auth 사용자를 지우거나 정지해도 이미 발급된 ID 토큰은 최대 1시간 유효합니다. 이 문서가 있고 <code>expireAt</code>이 지나지 않았으면 규칙(<code>isActiveUser()</code>)과 callable(<code>requireActiveUser</code>)이 그 계정의 새 쓰기를 거부합니다. 삭제한 계정이 데이터를 되살리거나, 정지한 계정이 계속 글을 쓰지 못하게 하기 위해서입니다.</li><li>클라이언트는 읽기·쓰기 모두 불가합니다.</li></ul><h2 id="서버-로그-멱등성" tabindex="-1">서버 로그 (멱등성) <a class="header-anchor" href="#서버-로그-멱등성" aria-label="Permalink to &quot;서버 로그 (멱등성)&quot;">​</a></h2><h3 id="notificationlogs-eventid" tabindex="-1"><code>notificationLogs/{eventId}</code> <a class="header-anchor" href="#notificationlogs-eventid" aria-label="Permalink to &quot;`notificationLogs/{eventId}`&quot;">​</a></h3><p><code>type</code>, <code>processed: true</code>, <code>createdAt</code>, <code>expireAt</code>(30일 뒤). 같은 알림을 두 번 보내지 않기 위한 기록입니다.</p><table tabindex="0"><thead><tr><th>이벤트 ID</th><th>의미</th></tr></thead><tbody><tr><td><code>circle_post_{gratitudeId}</code></td><td>Circle 새 글 알림 발송 완료</td></tr><tr><td><code>reaction_{gratitudeId}_{reactorUid}_{emoji}</code></td><td>리액션 알림 발송 완료</td></tr><tr><td><code>daily_reminder_{uid}_{YYYYMMDD}_{hour}</code></td><td>매일 알림 발송 완료</td></tr><tr><td><code>question_selected_{questionId}</code></td><td>질문 선정 알림 발송 완료</td></tr><tr><td><code>report_{reportId}</code></td><td>운영자 신고 알림 발송 완료</td></tr></tbody></table><h3 id="statslogs-markerid" tabindex="-1"><code>statsLogs/{markerId}</code> <a class="header-anchor" href="#statslogs-markerid" aria-label="Permalink to &quot;`statsLogs/{markerId}`&quot;">​</a></h3><p><code>type</code>, <code>createdAt</code>, <code>expireAt</code>(30일 뒤). 통계·댓글 수 갱신과 <strong>같은 트랜잭션</strong>에서 만들어 중복 집계를 막습니다.</p><table tabindex="0"><thead><tr><th>마커 ID</th><th>의미</th></tr></thead><tbody><tr><td><code>gratitude_{gratitudeId}</code></td><td>이 글이 <code>userStats</code>에 반영됨</td></tr><tr><td><code>comment_created_{gratitudeId}_{commentId}</code></td><td>댓글 수 +1 반영됨</td></tr><tr><td><code>comment_deleted_{gratitudeId}_{commentId}</code></td><td>댓글 수 −1 반영됨</td></tr></tbody></table><p>종류마다 접두사가 달라서, 클라이언트가 고르는 문서 ID로 다른 종류의 마커를 미리 만들 수 없습니다.</p><h2 id="기타" tabindex="-1">기타 <a class="header-anchor" href="#기타" aria-label="Permalink to &quot;기타&quot;">​</a></h2><h3 id="pushtokens-uid-tokens-token" tabindex="-1"><code>pushTokens/{uid}/tokens/{token}</code> <a class="header-anchor" href="#pushtokens-uid-tokens-token" aria-label="Permalink to &quot;`pushTokens/{uid}/tokens/{token}`&quot;">​</a></h3><p>웹: <code>token</code>, <code>platform</code>(<code>&quot;web&quot;</code>), <code>userAgent</code>, <code>createdAt</code>. 앱: <code>token</code>, <code>platform</code>(<code>&quot;ios&quot;</code> | <code>&quot;android&quot;</code>), <code>createdAt</code>. 서버는 <code>platform</code>으로 메시지 모양을 고릅니다(없으면 웹). 토큰 문자열 자체를 문서 ID로 써서 같은 기기의 재등록이 중복되지 않습니다. 발송 시 만료·무효 토큰은 서버가 지웁니다.</p><h3 id="feedback-id" tabindex="-1"><code>feedback/{id}</code> <a class="header-anchor" href="#feedback-id" aria-label="Permalink to &quot;`feedback/{id}`&quot;">​</a></h3><p><code>uid</code>, <code>type</code>, <code>message</code>(최대 2000자), <code>page</code>, <code>userAgent</code>, <code>createdAt</code>. 본인과 관리자만 읽을 수 있고 수정·삭제는 불가합니다.</p><h3 id="analyticsevents-id" tabindex="-1"><code>analyticsEvents/{id}</code> <a class="header-anchor" href="#analyticsevents-id" aria-label="Permalink to &quot;`analyticsEvents/{id}`&quot;">​</a></h3><p><code>uid</code>, <code>event</code>(최대 64자), <code>props</code>(map), <code>createdAt</code>(서버 시간). 클라이언트가 자기 uid로만 기록하고, 서버도 <code>badge_earned</code> 이벤트를 남깁니다. 관리자만 읽습니다. 계정을 삭제하면 그 사용자의 이벤트는 <code>uid: null</code>로 남습니다.</p><h2 id="ttl-정책" tabindex="-1">TTL 정책 <a class="header-anchor" href="#ttl-정책" aria-label="Permalink to &quot;TTL 정책&quot;">​</a></h2><p>Firestore TTL은 <code>firestore.indexes.json</code>의 <code>fieldOverrides</code>(<code>&quot;ttl&quot;: true</code>)로 선언하고 <code>firestore</code> 배포 때 함께 적용됩니다.</p><table tabindex="0"><thead><tr><th>컬렉션</th><th>필드</th><th>보관 기간</th></tr></thead><tbody><tr><td><code>notificationLogs</code></td><td><code>expireAt</code></td><td>30일</td></tr><tr><td><code>statsLogs</code></td><td><code>expireAt</code></td><td>30일</td></tr><tr><td><code>questionQuota</code></td><td><code>expireAt</code></td><td>다음 날(KST) 끝</td></tr><tr><td><code>reports</code></td><td><code>expireAt</code></td><td>닫힌 뒤 1년 (열린 신고에는 없음)</td></tr><tr><td><code>disabledUsers</code></td><td><code>expireAt</code></td><td>2시간</td></tr></tbody></table><p>TTL 삭제는 만료 즉시가 아니라 보통 하루 안쪽으로 지연될 수 있습니다. 만료 판단이 중요하다면 읽을 때도 <code>expireAt</code>을 직접 확인합니다(<code>disabledUsers</code>는 규칙과 함수 모두 <code>expireAt</code>을 비교함).</p><h2 id="인덱스" tabindex="-1">인덱스 <a class="header-anchor" href="#인덱스" aria-label="Permalink to &quot;인덱스&quot;">​</a></h2><table tabindex="0"><thead><tr><th>컬렉션</th><th>필드</th><th>쓰는 곳</th></tr></thead><tbody><tr><td><code>gratitudes</code></td><td><code>groupId ↑</code>, <code>createdAt ↓</code></td><td>Circle 피드, 오늘의 Circle 활동</td></tr><tr><td><code>gratitudes</code></td><td><code>userId ↑</code>, <code>createdAt ↓</code></td><td>내 기록, 캘린더, 공유 캘린더</td></tr><tr><td><code>gratitudes</code></td><td><code>userId ↑</code>, <code>isPublic ↑</code></td><td>배지 <code>shares</code> 조건(공개한 글 수)</td></tr><tr><td><code>badges</code></td><td><code>enabled ↑</code>, <code>sortOrder ↑</code></td><td>배지 목록</td></tr><tr><td><code>questions</code></td><td><code>status ↑</code>, <code>createdAt ↓</code></td><td>운영자 반려 목록</td></tr><tr><td><code>questions</code></td><td><code>status ↑</code>, <code>createdAt ↑</code></td><td>운영자 검토 대기열(오래된 순)</td></tr><tr><td><code>questions</code></td><td><code>authorId ↑</code>, <code>createdAt ↓</code></td><td>MyPage 내가 제안한 질문</td></tr><tr><td><code>users</code></td><td><code>notificationSettings.dailyReminder ↑</code>, <code>notificationSettings.dailyReminderHour ↑</code> (+ <code>dailyReminderMinute ↑</code>)</td><td>매일 알림 대상 조회 (정각 / 15·30·45분)</td></tr><tr><td><code>reports</code></td><td><code>status ↑</code>, <code>createdAt ↓</code></td><td>운영자 신고 대기열(최신순). 인덱스가 준비되기 전에는 클라이언트가 정렬</td></tr><tr><td><code>reports</code></td><td><code>status ↑</code>, <code>createdAt ↑</code></td><td>오래된 순 대기열용</td></tr><tr><td><code>reports</code></td><td><code>reporterId ↑</code>, <code>createdAt ↑</code></td><td>신고 도배 판단(24시간 안의 신고 수)</td></tr><tr><td><code>comments</code> (컬렉션 그룹, 단일 필드)</td><td><code>userId ↑</code></td><td>계정 삭제 때 사용자의 모든 댓글 찾기 (<code>fieldOverrides</code>)</td></tr></tbody></table>',90))])}const I=r(h,[["render",b]]);export{f as __pageData,I as default};
